create type public.app_role as enum ('management','intern');
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade not null, role public.app_role not null, unique(user_id,role));
grant select on public.user_roles to authenticated; grant all on public.user_roles to service_role;
alter table public.user_roles enable row level security;
create policy own_roles on public.user_roles for select to authenticated using (user_id=auth.uid());
create function public.has_role(_user_id uuid,_role public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=_user_id and role=_role) $$;
revoke execute on function public.has_role(uuid,public.app_role) from public,anon; grant execute on function public.has_role(uuid,public.app_role) to authenticated,service_role;
create table public.intern_profiles (user_id uuid primary key, full_name text not null default '', phone text not null default '', birth_date date, course text not null default '', institution text not null default '', academic_period integer not null default 1 check(academic_period>0), registration text not null default '', created_at timestamptz not null default now());
grant select,insert,update on public.intern_profiles to authenticated; grant all on public.intern_profiles to service_role;
alter table public.intern_profiles enable row level security;
create policy read_profile on public.intern_profiles for select to authenticated using (user_id=auth.uid() or public.has_role(auth.uid(),'management'));
create policy create_profile on public.intern_profiles for insert to authenticated with check(user_id=auth.uid());
create policy edit_profile on public.intern_profiles for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create table public.management_state (id integer primary key default 1 check(id=1), data jsonb not null default '{"vagas":[],"estagiarios":[],"instituicoes":[],"audit":[]}');
grant select,insert,update on public.management_state to authenticated; grant all on public.management_state to service_role;
alter table public.management_state enable row level security;
create policy management_only on public.management_state for all to authenticated using(public.has_role(auth.uid(),'management')) with check(public.has_role(auth.uid(),'management'));
create table public.public_vacancies (id text primary key, course text not null, sector text not null, unit text not null, kind text not null, weekly_hours integer not null check(weekly_hours between 1 and 30), start_date date not null, end_date date not null, status text not null);
grant select on public.public_vacancies to anon,authenticated; grant insert,update,delete on public.public_vacancies to authenticated; grant all on public.public_vacancies to service_role;
alter table public.public_vacancies enable row level security;
create policy public_read on public.public_vacancies for select to anon,authenticated using(true);
create policy management_write on public.public_vacancies for all to authenticated using(public.has_role(auth.uid(),'management')) with check(public.has_role(auth.uid(),'management'));
create table public.intern_assignments (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references public.intern_profiles(user_id), vacancy_id text not null, intern_data jsonb not null default '{}');
grant select,insert,update,delete on public.intern_assignments to authenticated; grant all on public.intern_assignments to service_role;
alter table public.intern_assignments enable row level security;
create policy own_assignment on public.intern_assignments for select to authenticated using(user_id=auth.uid());
create policy manage_assignment on public.intern_assignments for all to authenticated using(public.has_role(auth.uid(),'management')) with check(public.has_role(auth.uid(),'management'));
create function public.create_intern_account() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.user_roles(user_id,role) values(new.id,'intern'); insert into public.intern_profiles(user_id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name','')); return new; end $$;
create trigger create_intern_account after insert on auth.users for each row execute function public.create_intern_account();